python3 - <<'EOF'
import json, glob

total = 0
spans = 0
for path in sorted(glob.glob('data/*.jsonl')):
    subtotal = 0
    for line in open(path):
        line = line.strip()
        if not line:
            continue
        rec = json.loads(line)
        if rec.get('kind') != 'span':
            continue
        spans += 1
        elapsed = rec.get('body', {}).get('span', {}).get('elapsed')
        if elapsed is None:
            continue
        value, unit = elapsed['value'], elapsed['unit']
        if unit == 'ms':
            subtotal += value
        elif unit == 'us':
            subtotal += value // 1000
        elif unit == 's':
            subtotal += value * 1000
        else:
            raise ValueError(unit)
    print(path, subtotal)
    total += subtotal
print('spans:', spans, 'total:', total)
EOF
